              "namespace": "prod-catalog"
            },
            "snapshot": "NET_CAPTURE_01"
          }
        },
        {
          "input_pointer": "/pre_run_raw_providers/0/provider_fixture/state/network-policy-least-privilege-audit~1network_flow_observations/observation",
          "observed_value": {
            "capture_kind": "synthetic_independent_probe_snapshot",
            "flows": [
              {
                "application_request": "accepted",
                "destination_labels": {
                  "app": "backend"
                },
                "destination_namespace": "prod-catalog",
